package cli

import (
	"bytes"
	"strings"
	"sync"
	"testing"

	"github.com/spf13/cobra"
)

func TestWarnDeprecatedAliasOnce_PrintsOnce(t *testing.T) {
	t.Parallel()

	// Use unique replacement strings so this test doesn't collide with other
	// tests that also exercise the once-per-process map.
	old := "test-once-old"
	repl := "test-once-new"
	resetDeprecationOnceForKey(old, repl)

	var buf bytes.Buffer
	cmd := newAliasTestCommand(&buf)

	warnDeprecatedAliasOnce(cmd, old, repl)
	warnDeprecatedAliasOnce(cmd, old, repl)
	warnDeprecatedAliasOnce(cmd, old, repl)

	count := strings.Count(buf.String(), "deprecated")
	if count != 1 {
		t.Fatalf("expected exactly 1 deprecation line, got %d. Output:\n%s", count, buf.String())
	}
}

func TestWarnDeprecatedAliasOnce_DifferentPairsBothPrint(t *testing.T) {
	t.Parallel()

	resetDeprecationOnceForKey("alpha", "beta")
	resetDeprecationOnceForKey("gamma", "delta")

	var buf bytes.Buffer
	cmd := newAliasTestCommand(&buf)

	warnDeprecatedAliasOnce(cmd, "alpha", "beta")
	warnDeprecatedAliasOnce(cmd, "gamma", "delta")

	out := buf.String()
	if !strings.Contains(out, "alpha") || !strings.Contains(out, "beta") {
		t.Fatalf("missing first pair in output: %s", out)
	}
	if !strings.Contains(out, "gamma") || !strings.Contains(out, "delta") {
		t.Fatalf("missing second pair in output: %s", out)
	}
}

func TestFirstWord(t *testing.T) {
	t.Parallel()

	cases := map[string]string{
		"":             "",
		"configure":    "configure",
		"reset":        "reset",
		"reset --hard": "reset",
		"command  arg": "command",
		"\tleading":    "",
	}
	for in, want := range cases {
		if got := firstWord(in); got != want {
			t.Errorf("firstWord(%q) = %q, want %q", in, got, want)
		}
	}
}

// resetDeprecationOnceForKey clears any cached *sync.Once for the given pair
// so a test can assert printing behavior independently of other tests sharing
// the package-level map.
func resetDeprecationOnceForKey(old, replacement string) {
	deprecationWarnOnce.Delete(old + "->" + replacement)
}

func newAliasTestCommand(out *bytes.Buffer) *cobra.Command {
	cmd := &cobra.Command{Use: "fake"}
	cmd.SetOut(out)
	cmd.SetErr(out)
	return cmd
}

// guard against accidental concurrent access to the package map during the
// test suite. This is exported only via the import below so the linter sees
// sync as used in non-test contexts when this file compiles in isolation.
var _ sync.Mutex

package cli

import (
	"errors"
	"fmt"

	"github.com/charmbracelet/huh"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/spf13/cobra"
)

func newResetCmd() *cobra.Command {
	var forceFlag bool
	var sessionFlag string

	cmd := &cobra.Command{
		Use:        "reset",
		Short:      "Reset the shadow branch and session state for current HEAD",
		Deprecated: "use 'entire clean' instead (or 'entire clean --all' for repo-wide cleanup)",
		RunE: func(cmd *cobra.Command, _ []string) error {
			ctx := cmd.Context()

			// Check if in git repository before initializing logging,
			// to avoid creating .entire/logs in arbitrary directories.
			if _, err := paths.WorktreeRoot(ctx); err != nil {
				return errors.New("not a git repository")
			}

			// Initialize logging
			logging.SetLogLevelGetter(GetLogLevel)
			if err := logging.Init(ctx, ""); err == nil {
				defer logging.Close()
			}

			strat := GetStrategy(ctx)

			// Handle --session flag: delegate to clean's session logic
			if sessionFlag != "" {
				return runCleanSession(ctx, cmd, strat, sessionFlag, forceFlag, false, "Reset", "reset")
			}

			// Check for active sessions before bulk reset
			if !forceFlag {
				activeSessions, err := activeSessionsOnCurrentHead(ctx)
				if err != nil {
					fmt.Fprintf(cmd.ErrOrStderr(), "Warning: could not check for active sessions: %v\n", err)
					fmt.Fprintln(cmd.ErrOrStderr(), "Use --force to override.")
					return nil
				}
				if len(activeSessions) > 0 {
					fmt.Fprintln(cmd.ErrOrStderr(), "Active sessions detected on current HEAD:")
					for _, s := range activeSessions {
						fmt.Fprintf(cmd.ErrOrStderr(), "  %s (phase: %s)\n", s.SessionID, s.Phase)
					}
					fmt.Fprintln(cmd.ErrOrStderr(), "Use --force to override or wait for sessions to finish.")
					return nil
				}
			}

			if !forceFlag {
				var confirmed bool

				form := NewAccessibleForm(
					huh.NewGroup(
						huh.NewConfirm().
							Title("Reset session data?").
							Value(&confirmed),
					),
				)

				if err := form.Run(); err != nil {
					return handleFormCancellation(cmd.OutOrStdout(), "Reset", err)
				}

				if !confirmed {
					fmt.Fprintln(cmd.OutOrStdout(), "Reset cancelled.")
					return nil
				}
			}

			if err := strat.Reset(ctx, cmd.OutOrStdout(), cmd.ErrOrStderr()); err != nil {
				return fmt.Errorf("reset failed: %w", err)
			}

			return nil
		},
	}

	cmd.Flags().BoolVarP(&forceFlag, "force", "f", false, "Skip confirmation prompt and override active session guard")
	cmd.Flags().StringVar(&sessionFlag, "session", "", "Reset a specific session by ID")

	return cmd
}

package cli

import (
	"context"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/external"
	"github.com/entireio/cli/cmd/entire/cli/agent/types"
	"github.com/entireio/cli/cmd/entire/cli/interactive"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/session"
	"github.com/entireio/cli/cmd/entire/cli/settings"
	"github.com/entireio/cli/cmd/entire/cli/strategy"
	"github.com/entireio/cli/cmd/entire/cli/vercelconfig"

	"github.com/charmbracelet/huh"
	"github.com/spf13/cobra"
	"github.com/spf13/pflag"
)

// Config path display strings
const (
	configDisplayProject = ".entire/settings.json"
	configDisplayLocal   = ".entire/settings.local.json"
)

// Flag names used across setup commands.
const (
	agentFlagName            = "agent"
	flagCheckpointRemote     = "checkpoint-remote"
	flagSkipPushSessions     = "skip-push-sessions"
	flagSummarizeModel       = "summarize-model"
	flagSummarizeAgent       = "summarize-provider"
	checkpointProviderGitHub = "github"
)

// externalAgentsAutoEnabledNotice is printed when picking an external summary
// provider implicitly turns the external_agents setting on. It tells the user
// that the change applies beyond summary generation, without exposing the
// underlying flag name or discovery mechanics.
const externalAgentsAutoEnabledNotice = "Note: external agents are now enabled for the rest of Entire too — not just summaries."

// EnableOptions holds the flags for `entire enable`.
type EnableOptions struct {
	LocalDev            bool
	UseLocalSettings    bool
	UseProjectSettings  bool
	ForceHooks          bool
	SkipPushSessions    bool
	CheckpointRemote    string
	Telemetry           bool
	AbsoluteGitHookPath bool
	// SuppressDoneMessage tells `runEnableInteractive` to skip its final
	// "Ready." line and the "commit the configuration files" hint. Set
	// when the caller is running the bootstrap flow, which takes over
	// presentation of the final state (commit, push, done).
	SuppressDoneMessage bool
	Yes                 bool
}

// applyStrategyOptions sets strategy_options on settings from CLI flags.
func (opts *EnableOptions) applyStrategyOptions(settings *EntireSettings) {
	if opts.SkipPushSessions {
		if settings.StrategyOptions == nil {
			settings.StrategyOptions = make(map[string]interface{})
		}
		settings.StrategyOptions["push_sessions"] = false
	}
	if opts.CheckpointRemote != "" {
		provider, repo, err := parseCheckpointRemoteFlag(opts.CheckpointRemote)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Warning: invalid --checkpoint-remote format: %v\n", err)
		} else {
			if settings.StrategyOptions == nil {
				settings.StrategyOptions = make(map[string]interface{})
			}
			settings.StrategyOptions["checkpoint_remote"] = map[string]any{
				"provider": provider,
				"repo":     repo,
			}
		}
	}
}

func hasStrategyFlags(cmd *cobra.Command) bool {
	return cmd.Flags().Changed(flagCheckpointRemote) || cmd.Flags().Changed(flagSkipPushSessions)
}

func hasSummaryProviderFlags(cmd *cobra.Command) bool {
	return cmd.Flags().Changed(flagSummarizeAgent) || cmd.Flags().Changed(flagSummarizeModel)
}

// enableUsesSetupFlow reports whether `entire enable` should delegate to the
// setup/configure flow instead of the lightweight re-enable path.
// Bare `enable` and `enable --local/--project` remain state-toggle operations;
// any other setup-mutating flag should share configure's behavior.
func enableUsesSetupFlow(cmd *cobra.Command, agentName string) bool {
	if agentName != "" || hasStrategyFlags(cmd) {
		return true
	}

	return cmd.Flags().Changed("force") ||
		cmd.Flags().Changed("local-dev") ||
		cmd.Flags().Changed("absolute-git-hook-path") ||
		cmd.Flags().Changed("telemetry") ||
		cmd.Flags().Changed("yes")
}

func enableNeedsAgentManagement(cmd *cobra.Command) bool {
	return cmd.Flags().Changed("force") ||
		cmd.Flags().Changed("local-dev") ||
		cmd.Flags().Changed("absolute-git-hook-path") ||
		cmd.Flags().Changed("telemetry") ||
		cmd.Flags().Changed("yes")
}

// updateStrategyOptions applies strategy flags to settings without re-running agent setup.
// Loads and writes only the target file to avoid leaking settings between layers.
func updateStrategyOptions(ctx context.Context, w io.Writer, opts EnableOptions) error {
