func TestHideAsAlias_HidesAndDeprecates(t *testing.T) {
	t.Parallel()

	cmd := &cobra.Command{Use: "rewind"}
	got := hideAsAlias(cmd, "entire checkpoint rewind")

	if got != cmd {
		t.Fatal("hideAsAlias should return the same command instance")
